contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address _log) public payable {
        require(_log != address(0), "log address must be nonzero");

        // First SetLogFile must succeed because c has just been deployed and not initialized.
        bool firstReverted;
        c.SetLogFile(_log); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            firstReverted = true;
        } else {
            firstReverted = false;
        }

        // After a successful SetLogFile, the public Initialized() call permanently disables further SetLogFile calls.
        c.Initialized(); if (__ESBMC_reverted()) return;

        bool secondReverted;
        c.SetLogFile(_log); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            secondReverted = true;
        } else {
            secondReverted = false;
        }

        // General rule: before initialization SetLogFile succeeds; after Initialized it reverts.
        assert(firstReverted == false && secondReverted == true);
    }

    receive() external payable {}
}

